  {"question": "According to arXiv 2409.09041, which developers prohibit both political content and weapons-related content in their acceptable use policies?", "answer": "Anthropic, Cohere, OpenAI, and Stability AI prohibit both political and weapons-related content.", "evidence": [{"page": 5, "quote": "Political content, such as using foundation models for campaigning, lobbying, or otherwise influencing political processes, is explicitly prohibited by 9 startups-Anthropic, Character.AI, Cohere, Databricks, Midjourney, OpenAI, Perplexity, Stability AI, and Twelve Labs-whereas Big Tech companies like Amazon, Google, and Meta have no such prohibitions."}, {"page": 5, "quote": "Weaponsrelated content is explicitly prohibited by 7 developers: AI2, Anthropic, Amazon, Meta, Mistral, OpenAI, and Stability AI."}]},
  {"question": "In arXiv 2409.09041, which developers prohibit both model scraping and use for training competing services?", "answer": "Anthropic, Adept, Adobe, Meta, Perplexity, and Runway prohibit model scraping; 16 developers prohibit use for building competing services.", "evidence": [{"page": 5, "quote": "Anthropic's Acceptable Use Policy bans use of 'prompts and results to train an AI model (e.g., 'model scraping')'; Adept, Adobe, Meta, Perplexity, and Runway similarly prohibit the use of model outputs for training other foundation models. ...the remaining 16 prohibit the use of their models to build a competing service, which encompasses model scraping [109]."}]},
  {"question": "According to arXiv 2409.09041, what does the abbreviation 'AUP' stand for?", "answer": "'AUP' stands for 'acceptable use policy.'", "evidence": [{"page": 2, "quote": "In the context of foundation model development, an acceptable use policy is a policy from a developer that determines how a foundation model can or cannot be used."}]},
  {"question": "In arXiv 2409.09041, which developer's flagship model outputs audio, and what unique restriction does its AUP include?", "answer": "Eleven Labs' flagship model outputs audio and prohibits using its models to trick users into revealing passwords.", "evidence": [{"page": 5, "quote": "Eleven Labs, the only developer in Table 1 whose flagship model outputs audio, prohibits users from using its models to 'trick or mislead us or other users, especially in an attempt to learn sensitive account information, for example user passwords.'"}]},
  {"question": "Which developers, according to arXiv 2409.09041, have the highest number of prohibited use categories in their AUPs among closed developers?", "answer": "Anthropic (69), Cohere (46), and OpenAI (46) have the highest number among closed developers.", "evidence": [{"page": 4, "quote": "Among closed developers, the acceptable use policies of Anthropic (69 prohibited uses), Cohere (46), and OpenAI (46) explicitly reference the largest number of prohibited use categories,"}]} ,
  {"question": "Which category of prohibited content is most frequently referenced in developers' acceptable use policies in arXiv 2409.09041?", "answer": "Mis/disinformation is the most frequently prohibited category, with 26 policies including explicit prohibitions.", "evidence": [{"page": 3, "quote": "mis/disinformation (26 policies include explicit prohibitions), harassment/abuse (26), privacy (21), discrimination (21), and child harm/child sexual abuse material (21) were the most frequent,"}]}
]}
